CREATE TYPE "SubscriptionStatus" AS ENUM ('INCOMPLETE','TRIALING','ACTIVE','PAST_DUE','CANCELED','UNPAID','EXPIRED');
CREATE TABLE "WorkspaceSubscription" (
 "id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "planCode" TEXT NOT NULL, "status" "SubscriptionStatus" NOT NULL DEFAULT 'INCOMPLETE', "billingInterval" TEXT NOT NULL DEFAULT 'month', "provider" TEXT NOT NULL DEFAULT 'stripe', "providerCustomerId" TEXT, "providerSubscriptionId" TEXT, "providerPriceId" TEXT, "currentPeriodStart" TIMESTAMP(3), "currentPeriodEnd" TIMESTAMP(3), "cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT false, "canceledAt" TIMESTAMP(3), "trialEndsAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WorkspaceSubscription_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WorkspaceSubscription_workspaceId_key" ON "WorkspaceSubscription"("workspaceId");
CREATE UNIQUE INDEX "WorkspaceSubscription_providerCustomerId_key" ON "WorkspaceSubscription"("providerCustomerId");
CREATE UNIQUE INDEX "WorkspaceSubscription_providerSubscriptionId_key" ON "WorkspaceSubscription"("providerSubscriptionId");
CREATE INDEX "WorkspaceSubscription_status_currentPeriodEnd_idx" ON "WorkspaceSubscription"("status","currentPeriodEnd");
ALTER TABLE "WorkspaceSubscription" ADD CONSTRAINT "WorkspaceSubscription_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "BillingCustomer" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"email" TEXT,"name" TEXT,"provider" TEXT NOT NULL DEFAULT 'stripe',"providerCustomerId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BillingCustomer_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BillingCustomer_workspaceId_key" ON "BillingCustomer"("workspaceId"); CREATE UNIQUE INDEX "BillingCustomer_providerCustomerId_key" ON "BillingCustomer"("providerCustomerId");
ALTER TABLE "BillingCustomer" ADD CONSTRAINT "BillingCustomer_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "BillingInvoice" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"providerInvoiceId" TEXT,"number" TEXT,"status" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'usd',"amountDue" INTEGER NOT NULL DEFAULT 0,"amountPaid" INTEGER NOT NULL DEFAULT 0,"hostedUrl" TEXT,"invoicePdfUrl" TEXT,"periodStart" TIMESTAMP(3),"periodEnd" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "BillingInvoice_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BillingInvoice_providerInvoiceId_key" ON "BillingInvoice"("providerInvoiceId"); CREATE INDEX "BillingInvoice_workspaceId_createdAt_idx" ON "BillingInvoice"("workspaceId","createdAt");
ALTER TABLE "BillingInvoice" ADD CONSTRAINT "BillingInvoice_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "BillingPayment" ("id" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"providerPaymentId" TEXT,"status" TEXT NOT NULL,"amount" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'usd',"paidAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "BillingPayment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BillingPayment_providerPaymentId_key" ON "BillingPayment"("providerPaymentId"); CREATE INDEX "BillingPayment_invoiceId_status_idx" ON "BillingPayment"("invoiceId","status");
ALTER TABLE "BillingPayment" ADD CONSTRAINT "BillingPayment_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "BillingInvoice"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "BillingWebhookEvent" ("id" TEXT NOT NULL,"providerEventId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"processedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "BillingWebhookEvent_pkey" PRIMARY KEY ("id"));
